import static org.mockito.Mockito.never;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class AbstractScopeBuilder_visit_TriageGen1Test {

    @Mock
    private NodeTraversal t;
    @Mock
    private Node n;
    @Mock
    private Node parent;
    @Mock
    private Node firstChild;
    @Mock
    private Node nextChild;
    @Mock
    private Node input;

    private TypedScopeCreator.AbstractScopeBuilder scopeBuilder;

    @Before
    public void setUp() {
        // We use a spy to test the visit method while mocking internal calls to other methods 
        // like attachLiteralTypes, checkForClassDefiningCalls, etc.
        scopeBuilder = spy(new TypedScopeCreator.AbstractScopeBuilder(
                mock(Compiler.Configuration.class),
                mock(ErrorReporter.class),
                mock(ScopeManager.class),
                mock(ScopeCreator.class)));

        // Mock basic behaviors to avoid NullPointerException
        doNothing().when(scopeBuilder).attachLiteralTypes(any(), any());
    }

    @Test
    public void testVisit_Call() {
        when(t.getInputId()).thenReturn("testId");
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.CALL);

        doNothing().when(scopeBuilder).checkForClassDefiningCalls(eq(t), eq(n), eq(parent));
        doNothing().when(scopeBuilder).checkForCallingConventionDefiningCalls(eq(n), any());

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).checkForClassDefiningCalls(t, n, parent);
        verify(scopeBuilder).checkForCallingConventionDefiningCalls(eq(n), any());
    }

    @Test
    public void testVisit_Function_NonExtern() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.FUNCTION);
        when(t.getInput()).thenReturn(input);
        when(input.isExtern()).thenReturn(false);
        when(input.isGetProp()).thenReturn(false); // Dummy for safety

        // Mock NodeUtil.isHoistedFunctionDeclaration via a mock if possible, 
        // but since it's a static util, we assume it returns false for this test setup.
        // In a real scenario, we'd use PowerMock if we needed to mock NodeUtil.
        doNothing().when(scopeBuilder).defineFunctionLiteral(eq(n), eq(parent));

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).defineFunctionLiteral(n, parent);
    }

    @Test
    public void testVisit_Function_Extern() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.FUNCTION);
        when(t.getInput()).thenReturn(input);
        when(input.isExtern()).thenReturn(true);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder, never()).defineFunctionLiteral(any(), any());
    }

    @Test
    public void testVisit_Assign_QualifiedName() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.ASSIGN);
        when(n.getFirstChild()).thenReturn(firstChild);
        when(firstChild.isGetProp()).thenReturn(true);
        when(firstChild.isQualifiedName()).thenReturn(true);
        when(firstChild.getNext()).thenReturn(nextChild);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).maybeDeclareQualifiedName(eq(t), any(), eq(firstChild), eq(n), eq(nextChild));
    }

    @Test
    public void testVisit_Assign_NotQualified() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.ASSIGN);
        when(n.getFirstChild()).thenReturn(firstChild);
        when(firstChild.isGetProp()).thenReturn(false);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder, never()).maybeDeclareQualifiedName(any(), any(), any(), any(), any());
    }

    @Test
    public void testVisit_Catch() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.CATCH);
        doNothing().when(scopeBuilder).defineCatch(eq(n), eq(parent));

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).defineCatch(n, parent);
    }

    @Test
    public void testVisit_Var() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.VAR);
        doNothing().when(scopeBuilder).defineVar(eq(n), eq(parent));

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).defineVar(n, parent);
    }

    @Test
    public void testVisit_GetProp_Qualified() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.GETPROP);
        when(parent.isExprResult()).thenReturn(true);
        when(n.isQualifiedName()).thenReturn(true);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder).maybeDeclareQualifiedName(eq(t), any(), eq(n), eq(parent), eq(null));
    }

    @Test
    public void testVisit_GetProp_NotQualified() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.GETPROP);
        when(parent.isExprResult()).thenReturn(true);
        when(n.isQualifiedName()).thenReturn(false);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder, never()).maybeDeclareQualifiedName(any(), any(), any(), any(), any());
    }

    @Test
    public void testVisit_GetProp_NotExprResult() {
        when(n.getType()).thenReturn(com.google.javascript.jscomp.Token.GETPROP);
        when(parent.isExprResult()).thenReturn(false);

        scopeBuilder.visit(t, n, parent);

        verify(scopeBuilder, never()).maybeDeclareQualifiedName(any(), any(), any(), any(), any());
    }
}
